export const getGoogleDrivePosterUrl = (qid?: string | null): string | null => {
  if (!qid) return null;
  const cleanQid = qid.trim().toUpperCase();
  const fileId = GOOGLE_DRIVE_POSTER_MAP[cleanQid];
  if (!fileId) return null;
  return `https://lh3.googleusercontent.com/d/${fileId}`;
};

export interface MoviePosterResolution {
  primaryUrl: string;
  fallbackUrl?: string;
  isGoogleDrive: boolean;
}

/**
 * Resolves poster following strict priority:
 * 1. Google Drive poster (either already saved in posterUrl or matching wikidataId in the Drive catalog)
 * 2. Amazon, Wikimedia Commons, Wikipedia upload, TMDB, or Archive.org
 */
export const resolveMoviePoster = (movie: {
  wikidataId?: string | null;
  posterUrl?: string | null;
  title?: string;
}): MoviePosterResolution => {
  const driveFromQid = getGoogleDrivePosterUrl(movie.wikidataId);
  const rawPoster = movie.posterUrl || '';
  const isPosterGoogleDrive = rawPoster.includes('lh3.googleusercontent.com') || rawPoster.includes('drive.google.com');

  if (isPosterGoogleDrive) {
    return {
      primaryUrl: rawPoster,
      fallbackUrl: driveFromQid && driveFromQid !== rawPoster ? driveFromQid : undefined,
      isGoogleDrive: true
    };
  }

  if (driveFromQid) {
    return {
      primaryUrl: driveFromQid,
      fallbackUrl: rawPoster || undefined, // Fallback to Amazon / Wikimedia Commons / etc.
      isGoogleDrive: true
    };
  }

  return {
    primaryUrl: rawPoster,
    fallbackUrl: undefined,
    isGoogleDrive: false
  };
};
